1	import { requireArea } from "@/lib/rbac";
2	import { PageHeader, Badge } from "@/components/ui/primitives";
3	import { MailAnalytics } from "@/components/admin/MailAnalytics";
4	import { refreshMailStats } from "@/lib/actions-mail-admin";
5	
6	export const dynamic = "force-dynamic";
7	
8	export default async function AdminMailPage() {
9	  await requireArea("platform");
10	
11	  // Server-render an initial snapshot; the client component then polls.
12	  const initial = await refreshMailStats();
13	
14	  const tone =
15	    initial.state === "ok" ? "green" : initial.state === "unconfigured" ? "amber" : "red";
16	  const label =
17	    initial.state === "ok"
18	      ? "connected"
19	      : initial.state === "unconfigured"
20	        ? "not configured"
21	        : "unreachable";
22	
23	  return (
24	    <div>
25	      <PageHeader
26	        title="Mail deliverability"
27	        sub="Live Mailcow delivery + spam analytics for hosted business-email domains."
28	      >
29	        <Badge tone={tone}>{label}</Badge>
30	      </PageHeader>
31	
32	      <MailAnalytics initial={initial} />
33	    </div>
34	  );
35	}
