1	import Link from "next/link";
2	import { requireUser } from "@/lib/auth";
3	import { EmptyState } from "@/components/ui/primitives";
4	import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
5	import {
6	  listFolders,
7	  listMessages,
8	  getMailboxes,
9	} from "@/lib/actions-mail";
10	import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
11	import { mailAccessState, type MailAccessState } from "@/lib/mail/imap";
12	import { MailClient } from "@/components/customer/mail/MailClient";
13	import { PortalHero } from "@/components/portal/PortalHero";
14	
15	export const dynamic = "force-dynamic";
16	
17	export const metadata = { title: "Mail — Nxeon" };
18	
19	export default async function MailPage({
20	  searchParams,
21	}: {
22	  searchParams: Promise<{ mailbox?: string }>;
23	}) {
24	  const user = await requireUser();
25	  const { mailbox: requested } = await searchParams;
26	
27	  let folders: MailFolder[] = [];
28	  let mailboxes: MailboxInfo[] = [];
29	  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
30	  let inboxPath = "INBOX";
31	  let signature = "";
32	  let active: string | undefined;
33	  let failed = false;
34	
35	  const wanted = requested?.trim().toLowerCase();
36	
37	  try {
38	    if (wanted) {
39	      // Honour `?mailbox=` (the per-mailbox "Open inbox" link on the Business
40	      // Email page) but ONLY when the address is one this user actually owns.
41	      // `getMailboxes` is already scoped to their own subscriptions, so an
42	      // address outside that list is dropped rather than passed to
43	      // `resolveMailbox` — a bad or hostile value lands on the default mailbox
44	      // instead of turning the whole page into an error state. The mailbox list
45	      // has to be resolved first here, hence the extra round trip.
46	      mailboxes = await getMailboxes();
47	      if (mailboxes.length === 0) throw new Error("no mailbox");
48	      if (mailboxes.some((m) => m.address.toLowerCase() === wanted)) active = wanted;
49	      folders = await listFolders(active);
50	    } else {
51	      // No deep link: `resolveMailbox(undefined)` and `getMailboxes` both order by
52	      // createdAt asc, so they agree on which mailbox is the default and the two
53	      // IMAP round trips can overlap — this is the common load and it stays fast.
54	      const [f, mb] = await Promise.all([listFolders(), getMailboxes()]);
55	      folders = f;
56	      mailboxes = mb;
57	    }
58	
59	    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
60	    list = await listMessages(inboxPath, 1, undefined, active);
61	    // Signature for the active mailbox (best effort — never fail the page on it).
62	    signature = await getMailboxSettings(active)
63	      .then((s) => s.signature)
64	      .catch(() => "");
65	  } catch {
66	    failed = true;
67	  }
68	
69	  if (failed || folders.length === 0) {
70	    // WHY a diagnosis instead of one message: this page used to render a single
71	    // "No mailbox connected" for every cause, so "you have no email plan",
72	    // "your domain isn't verified yet", "your mailbox exists but we never
73	    // captured its password" and "the mail server is down" all read as the same
74	    // dead end. `mailAccessState` also runs Mailcow discovery, so a mailbox that
75	    // exists on the mail server without a local row is adopted BEFORE we tell
76	    // anyone they don't have one — the "it's not detecting the mailbox I already
77	    // have" report.
78	    const state = await mailAccessState(user.id).catch(
79	      () => ({ kind: "no-subscription" }) as MailAccessState,
80	    );
81	    return (
82	      <div className="mx-auto max-w-2xl pt-10">
83	        <MailUnavailable state={state} />
84	      </div>
85	    );
86	  }
87	
88	  // The shared dashboard <main> wraps every route in `max-w-7xl px-4 py-8
89	  // sm:px-6`. Mail is a full-app surface, so we cancel that padding with
90	  // negative margins to let the client run full-height (no blank space below)
91	  // and edge-to-edge up to the layout's max width. Going wider than max-w-7xl
92	  // on very large monitors would require editing the shared layout, which this
93	  // route intentionally leaves untouched.
94	  return (
95	    <>
96	      <PortalHero variant="mail" title="Inbox" sub="Read and send from your Nxeon mailboxes." />
97	      <div className="h-full">
98	        <MailClient
99	          initialFolders={folders}
100	          initialMailboxes={mailboxes}
101	          initialList={list}
102	          initialFolderPath={inboxPath}
103	          initialSignature={signature}
104	          initialActiveAddress={active}
105	        />
106	      </div>
107	    </>
108	  );
109	}
110	
111	/** One empty state per real cause, each with the action that actually fixes it. */
112	function MailUnavailable({ state }: { state: MailAccessState }) {
113	  const emailLink = (
114	    <Link href="/dashboard/email" className="btn-primary">
115	      Business Email
116	    </Link>
117	  );
118	
119	  switch (state.kind) {
120	    case "no-subscription":
121	      return (
122	        <EmptyState
123	          title="No email plan yet"
124	          sub="Webmail needs a mailbox on one of your domains. Add business email to a domain and your inbox appears here."
125	          action={
126	            <Link href="/dashboard/email" className="btn-primary">
127	              Set up email
128	            </Link>
129	          }
130	        />
131	      );
132	
133	    case "unverified-domain":
134	      return (
135	        <EmptyState
136	          title="Finish verifying your domain"
137	          sub={`${state.domains.join(", ")} still needs its DNS records published and verified. Mailboxes can't go live — and mail won't route — until that succeeds.`}
138	          action={emailLink}
139	        />
140	      );
141	
142	    case "no-mailbox":
143	      return (
144	        <EmptyState
145	          title="No mailbox created yet"
146	          sub={`${state.domains.join(", ")} is verified and ready. Create your first mailbox (like you@${state.domains[0] ?? "yourdomain.com"}) to start using webmail.`}
147	          action={emailLink}
148	        />
149	      );
150	
151	    case "no-password":
152	      return (
153	        <EmptyState
154	          title="Reset your mailbox password to continue"
155	          sub={`We can see ${state.address} on the mail server, but we don't hold a password for it — so we can't sign in to IMAP on your behalf. Reset the password on the Business Email page and webmail will open here.`}
156	          action={emailLink}
157	        />
158	      );
159	
160	    case "server-unreachable":
161	      return (
162	        <EmptyState
163	          title="Couldn't reach your mailbox"
164	          sub={`${state.address} is set up, but the mail server didn't answer just now. This is usually temporary — reload in a moment. If it keeps happening, open a ticket and we'll look at the server.`}
165	          action={
166	            <Link href="/dashboard/support" className="btn-secondary">
167	              Contact support
168	            </Link>
169	          }
170	        />
171	      );
172	
173	    default:
174	      return (
175	        <EmptyState
176	          title="No mailbox connected"
177	          sub="We couldn't reach a mailbox for your account."
178	          action={emailLink}
179	        />
180	      );
181	  }
182	}
