1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState, useTransition } from "react";
4	import type {
5	  MailFolder,
6	  MailboxInfo,
7	  ListResult,
8	  MessageSummary,
9	  MessageFull,
10	  SendPayload,
11	} from "@/lib/mail/types";
12	import {
13	  listFolders,
14	  listMessages,
15	  getMessage,
16	  getMailboxes,
17	  sendMessage,
18	  setFlag,
19	  moveMessage,
20	  deleteMessage,
21	  markSpam,
22	  markNotSpam,
23	  blockSender,
24	} from "@/lib/actions-mail";
25	import { getMailboxSettings } from "@/lib/actions-mailbox-settings";
26	import { FolderRail, MiniRail, type RailItem } from "./FolderRail";
27	import { MessageList } from "./MessageList";
28	import { ReadingPane } from "./ReadingPane";
29	import { ContactPanel } from "./ContactPanel";
30	import { useCompose, MAIL_SENT_EVENT } from "./ComposeProvider";
31	import { MailSettings } from "./MailSettings";
32	import { ShortcutHelp } from "./ShortcutHelp";
33	import { Icon, displayName, categoryOf, type MailTab } from "./util";
34	
35	const STARRED = "__starred__";
36	const SNOOZED = "__snoozed__";
37	
38	// Remembers the last mailbox the user picked so it stays the default across
39	// reloads and re-logins (until they switch to a different one). A single stable
40	// key is fine here: the mailbox list is already scoped to the logged-in user, and
41	// we only ever restore an address that still appears in that list.
42	const SELECTED_MAILBOX_KEY = "nxeon.mail.selectedMailbox";
43	
44	/** Per-mailbox signature config used when composing. */
45	type SigConfig = {
46	  enabled: boolean;
47	  onReply: boolean;
48	  placement: "above" | "below";
49	  plain: string; // plain-text fallback / derived text part
50	  html: string; // sanitized rich-signature HTML
51	};
52	
53	const ROLE_META: Record<string, { label: string; icon: RailItem["icon"]; order: number }> = {
54	  inbox: { label: "Inbox", icon: "inbox", order: 0 },
55	  sent: { label: "Sent", icon: "sent", order: 3 },
56	  drafts: { label: "Drafts", icon: "draft", order: 4 },
57	  junk: { label: "Spam", icon: "spam", order: 5 },
58	  trash: { label: "Trash", icon: "trash", order: 6 },
59	  archive: { label: "Archive", icon: "archive", order: 7 },
60	};
61	
62	export function MailClient({
63	  initialFolders,
64	  initialMailboxes,
65	  initialList,
66	  initialFolderPath,
67	  initialSignature = "",
68	  initialActiveAddress,
69	  loadMailboxes = getMailboxes,
70	}: {
71	  initialFolders: MailFolder[];
72	  initialMailboxes: MailboxInfo[];
73	  initialList: ListResult;
74	  initialFolderPath: string;
75	  initialSignature?: string;
76	  /**
77	   * How the switcher (re)loads the mailbox list. Defaults to the customer's own
78	   * mailboxes (`getMailboxes`); the admin company-inbox passes a company-scoped
79	   * loader so the two lists never bleed into each other.
80	   */
81	  loadMailboxes?: () => Promise<MailboxInfo[]>;
82	  /**
83	   * Mailbox the server already loaded folders and messages for (the `?mailbox=`
84	   * deep link from a mailbox row on the Business Email page). It MUST match what
85	   * the server rendered: seeding this from anything else would show one
86	   * mailbox's messages under another mailbox's name until the first refetch.
87	   * The server only sets it after confirming the address belongs to this user.
88	   */
89	  initialActiveAddress?: string;
90	}) {
91	  const [folders, setFolders] = useState<MailFolder[]>(initialFolders);
92	  const [mailboxes, setMailboxes] = useState<MailboxInfo[]>(initialMailboxes);
93	  const [activeAddress, setActiveAddress] = useState<string | undefined>(
94	    initialActiveAddress ?? initialMailboxes[0]?.address,
95	  );
96	  const [selected, setSelected] = useState<string>(initialFolderPath);
97	  const [list, setList] = useState<ListResult>(initialList);
98	  const [page, setPage] = useState(1);
99	  const [tab, setTab] = useState<MailTab>("primary");
100	  const [search, setSearch] = useState("");
101	
102	  const [selectedUid, setSelectedUid] = useState<number | null>(null);
103	  const [cursorUid, setCursorUid] = useState<number | null>(null);
104	  const [message, setMessage] = useState<MessageFull | null>(null);
105	  const [msgLoading, setMsgLoading] = useState(false);
106	
107	  // The composer lives at the shell level (ComposeProvider) so it stays mounted —
108	  // and its in-progress draft survives — across navigation to other dashboard
109	  // pages, and so `position: fixed` resolves to the real viewport. We drive it
110	  // purely through this context instead of rendering <Composer> inline.
111	  const compose = useCompose();
112	  const [sig, setSig] = useState<SigConfig>({
113	    enabled: true,
114	    onReply: true,
115	    placement: "below",
116	    plain: initialSignature,
117	    html: "",
118	  });
119	  const [showSettings, setShowSettings] = useState(false);
120	  const [mobilePane, setMobilePane] = useState<"list" | "read">("list");
121	  const [railOpen, setRailOpen] = useState(false);
122	  const [refreshing, setRefreshing] = useState(false);
123	  const [toast, setToast] = useState<string | null>(null);
124	  const [showHelp, setShowHelp] = useState(false);
125	
126	  // Collapsible panels — desktop only, persisted so the layout choice sticks.
127	  const [railCollapsed, setRailCollapsed] = useState(false);
128	  const [contactCollapsed, setContactCollapsed] = useState(false);
129	  useEffect(() => {
130	    try {
131	      if (localStorage.getItem("nxeon.mail.railCollapsed") === "1") setRailCollapsed(true);
132	      if (localStorage.getItem("nxeon.mail.contactCollapsed") === "1") setContactCollapsed(true);
133	    } catch {}
134	  }, []);
135	  const toggleRail = useCallback(() => {
136	    setRailCollapsed((v) => {
137	      const next = !v;
138	      try { localStorage.setItem("nxeon.mail.railCollapsed", next ? "1" : "0"); } catch {}
139	      return next;
140	    });
141	  }, []);
142	  const toggleContact = useCallback(() => {
143	    setContactCollapsed((v) => {
144	      const next = !v;
145	      try { localStorage.setItem("nxeon.mail.contactCollapsed", next ? "1" : "0"); } catch {}
146	      return next;
147	    });
148	  }, []);
149	
150	  const [listPending, startList] = useTransition();
151	  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
152	
153	  const mailbox = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0] ?? null;
154	
155	  /* ---- Signature config (loaded per active mailbox) --------------------- */
156	  const loadSig = useCallback((addr?: string) => {
157	    getMailboxSettings(addr)
158	      .then((s) =>
159	        setSig({
160	          enabled: s.signatureEnabled,
161	          onReply: s.signatureOnReply,
162	          placement: s.signaturePlacement,
163	          plain: s.signature,
164	          html: s.signatureHtml,
165	        }),
166	      )
167	      .catch(() => {});
168	  }, []);
169	
170	  useEffect(() => {
171	    loadSig(activeAddress);
172	  }, [activeAddress, loadSig]);
173	
174	  /** Signature fields to spread into a compose draft, honouring the toggles. */
175	  const sigFields = useCallback(
176	    (isReply: boolean) => {
177	      if (!sig.enabled) return {};
178	      if (isReply && !sig.onReply) return {};
179	      return {
180	        signature: sig.plain || undefined,
181	        signatureHtml: sig.html || undefined,
182	        signaturePlacement: sig.placement,
183	      };
184	    },
185	    [sig],
186	  );
187	
188	  const inboxPath = folders.find((f) => f.role === "inbox")?.path ?? "INBOX";
189	  const archivePath = folders.find((f) => f.role === "archive")?.path;
190	  const trashPath = folders.find((f) => f.role === "trash")?.path;
191	  const junkPath = folders.find((f) => f.role === "junk")?.path;
192	
193	  /* ---- Rail model ------------------------------------------------------- */
194	  const byRole = (role: string) => folders.find((f) => f.role === role);
195	  const primaryItems: RailItem[] = [];
196	  const inbox = byRole("inbox");
197	  primaryItems.push({ key: inbox?.path ?? "INBOX", label: "Inbox", icon: "inbox", unread: inbox?.unread });
198	  primaryItems.push({ key: STARRED, label: "Starred", icon: "star", virtual: true });
199	  primaryItems.push({ key: SNOOZED, label: "Snoozed", icon: "clock", virtual: true });
200	  for (const role of ["sent", "drafts", "junk", "trash", "archive"] as const) {
201	    const f = byRole(role);
202	    const meta = ROLE_META[role];
203	    if (f) primaryItems.push({ key: f.path, label: meta.label, icon: meta.icon, unread: f.unread });
204	    else primaryItems.push({ key: `__missing_${role}`, label: meta.label, icon: meta.icon });
205	  }
206	  const customItems: RailItem[] = folders
207	    .filter((f) => f.role === "custom")
208	    .map((f) => ({ key: f.path, label: f.name, icon: "folder" as const, unread: f.unread }));
209	
210	  const labelFor = useCallback(
211	    (key: string): string => {
212	      if (key === STARRED) return "Starred";
213	      if (key === SNOOZED) return "Snoozed";
214	      const f = folders.find((x) => x.path === key);
215	      if (f) return ROLE_META[f.role]?.label ?? f.name;
216	      return "Mailbox";
217	    },
218	    [folders]
219	  );
220	
221	  const resolvePath = (key: string): string | null => {
222	    if (key === SNOOZED) return null;
223	    if (key === STARRED) return inboxPath;
224	    if (key.startsWith("__missing_")) return null;
225	    return key;
226	  };
227	
228	  /* ---- Loading ---------------------------------------------------------- */
229	  const loadList = useCallback(
230	    (key: string, pageNum: number, q: string, addr = activeAddress) => {
231	      const path = resolvePath(key);
232	      if (path === null) {
233	        setList({ messages: [], total: 0, page: 1, pageSize: initialList.pageSize });
234	        return;
235	      }
236	      startList(async () => {
237	        try {
238	          const res = await listMessages(path, pageNum, q || undefined, addr);
239	          if (key === STARRED) {
240	            const flagged = res.messages.filter((m) => m.flagged);
241	            setList({ messages: flagged, total: flagged.length, page: 1, pageSize: res.pageSize });
242	          } else {
243	            setList(res);
244	          }
245	        } catch {
246	          setToast("Couldn't load messages.");
247	        }
248	      });
249	    },
250	    [inboxPath, initialList.pageSize, activeAddress]
251	  );
252	
253	  const selectFolder = (key: string) => {
254	    setSelected(key);
255	    setPage(1);
256	    setRailOpen(false);
257	    setSelectedUid(null);
258	    setCursorUid(null);
259	    setMessage(null);
260	    setMobilePane("list");
261	    loadList(key, 1, search);
262	  };
263	
264	  /* ---- Mailbox switching ------------------------------------------------ */
265	  const switchMailbox = async (address: string) => {
266	    if (address === activeAddress) return;
267	    setActiveAddress(address);
268	    // Persist the choice so it becomes the default on the next load / re-login.
269	    try { localStorage.setItem(SELECTED_MAILBOX_KEY, address); } catch {}
270	    setSelectedUid(null);
271	    setCursorUid(null);
272	    setMessage(null);
273	    setMobilePane("list");
