"use server";

/**
 * Admin-only management of COMPANY mailboxes on the Nxeon domain (admin@,
 * support@, santino@, and any more the admin creates) — free.
 *
 * These are deliberately decoupled from the customer email-hosting model
 * (EmailSubscription / EmailPlan / Mailbox): a company mailbox is a
 * `CompanyMailbox` row + a Mailcow mailbox, and nothing else. No wallet debit,
 * no plan limit, no subscription — "free" is structural, not a discount.
 *
 * SECURITY. Every export authenticates with `requireArea("platform")` (ADMIN-only)
 * INSIDE the function before touching Mailcow or the database, and returns a typed
 * { ok, error? } result rather than throwing raw internals at the client. The
 * mailbox password is generated server-side, stored AES-256-GCM encrypted
 * (lib/crypto-box), and only ever returned to the admin on explicit reveal/reset.
 */
import { db } from "./db";
import { requireArea } from "./rbac";
import { encryptSecret, decryptSecret } from "./crypto-box";
import { randomBytes } from "node:crypto";
import {
  COMPANY_MAIL_DOMAIN,
  DEFAULT_COMPANY_LOCALPARTS,
  type CompanyMailboxRow,
} from "./company-mail-core";
import type { MailboxInfo } from "./mail/types";
import {
  mailcowConfigured,
  mcDomainExists,
  mcCreateDomain,
  mcCreateMailbox,
  mcDeleteMailbox,
  mcSetMailboxPassword,
  mcListMailboxes,
  isMailcowUnreachable,
} from "./mailcow";

/** Default quota for a company mailbox. */
const DEFAULT_QUOTA_MB = 2048;

type Ok<T> = { ok: true } & T;
type Err = { ok: false; error: string };

/** Lower-case, validate a local part (the bit before @). */
function normalizeLocalPart(raw: string): string | null {
  const lp = String(raw ?? "").trim().toLowerCase();
  // RFC-ish, conservative: start/end alphanumeric, dots/dashes/underscores inside.
  if (!/^[a-z0-9](?:[a-z0-9._-]{0,61}[a-z0-9])?$/.test(lp)) return null;
  return lp;
}

/** A strong, URL-safe mailbox password. */
function generatePassword(): string {
  return randomBytes(18).toString("base64url");
}

/** Map an unknown error to a safe, user-facing string. */
function safeMailError(err: unknown): string {
  if (isMailcowUnreachable(err)) {
    return "The mail server is unreachable right now. Please try again shortly.";
  }
  const msg = err instanceof Error ? err.message : String(err);
  // Mailcow "danger" messages are already terse and safe to surface.
  return msg && msg.length < 200 ? msg : "The mail server rejected the request.";
}

/** Ensure the company domain exists in Mailcow (idempotent, best-effort create). */
async function ensureDomain(): Promise<void> {
  if (await mcDomainExists(COMPANY_MAIL_DOMAIN)) return;
  await mcCreateDomain(COMPANY_MAIL_DOMAIN);
}

async function audit(userId: string, action: string, detail: string): Promise<void> {
  try {
    await db.auditLog.create({ data: { userId, action, detail } });
  } catch {
    /* audit is best-effort — never fail the operation on a logging error */
  }
}

/**
 * List every company mailbox. Merges live quota usage from Mailcow when it is
 * reachable; falls back to DB-only rows (usedMB: null) if it is not.
 */
export async function listCompanyMailboxes(): Promise<CompanyMailboxRow[]> {
  await requireArea("platform");
  const rows = await db.companyMailbox.findMany({ orderBy: { address: "asc" } });

  const usedByAddress = new Map<string, number>();
  try {
    if (mailcowConfigured()) {
      const live = await mcListMailboxes(COMPANY_MAIL_DOMAIN);
      for (const m of live) {
        usedByAddress.set(m.address.toLowerCase(), Math.round(m.quotaUsedBytes / (1024 * 1024)));
      }
    }
  } catch {
    /* Mailcow unreachable — show DB rows without live usage */
  }

  return rows.map((r) => ({
    id: r.id,
    address: r.address,
    label: r.label,
    quotaMB: r.quotaMB,
    status: r.status,
    createdAt: r.createdAt.toISOString(),
    usedMB: usedByAddress.has(r.address.toLowerCase()) ? usedByAddress.get(r.address.toLowerCase())! : null,
  }));
}

/**
 * The company mailboxes as `MailboxInfo` for the admin webmail switcher. This is
 * the admin-portal equivalent of the customer `getMailboxes()` — it is what keeps
 * company mail OUT of the customer switcher (that one no longer lists them).
 * ADMIN-only (delegates to the guarded `listCompanyMailboxes`).
 */
export async function listCompanyMailboxInfos(): Promise<MailboxInfo[]> {
  await requireArea("platform");
  const rows = await listCompanyMailboxes();
  return rows.map((r) => ({
    address: r.address,
    usedBytes: (r.usedMB ?? 0) * 1024 * 1024,
    quotaBytes: r.quotaMB * 1024 * 1024,
  }));
}

/**
 * Create a free company mailbox. Provisions it on Mailcow, stores the encrypted
 * password, and returns the generated password ONCE (so the admin can hand it to
 * whoever owns the address / sign in to webmail).
 */
export async function createCompanyMailbox(
  localPartRaw: string,
  labelRaw?: string
): Promise<Ok<{ address: string; password: string }> | Err> {
  const admin = await requireArea("platform");
  if (!mailcowConfigured()) {
    return { ok: false, error: "Mail hosting is not configured (MAILCOW_API_URL / MAILCOW_API_KEY)." };
  }
  const localPart = normalizeLocalPart(localPartRaw);
  if (!localPart) {
    return { ok: false, error: "Enter a valid mailbox name (letters, numbers, dots, dashes)." };
  }
  const address = `${localPart}@${COMPANY_MAIL_DOMAIN}`;

  const existing = await db.companyMailbox.findUnique({ where: { address } });
  if (existing) return { ok: false, error: `${address} already exists.` };

  const label = labelRaw?.trim() ? labelRaw.trim().slice(0, 80) : null;
  const password = generatePassword();

  try {
    await ensureDomain();
    await mcCreateMailbox({
      localPart,
      domain: COMPANY_MAIL_DOMAIN,
      name: label ?? localPart,
      password,
      quotaMB: DEFAULT_QUOTA_MB,
    });
  } catch (err) {
    return { ok: false, error: safeMailError(err) };
  }

  await db.companyMailbox.create({
    data: {
      address,
      label,
      passwordEnc: encryptSecret(password),
      quotaMB: DEFAULT_QUOTA_MB,
      status: "ACTIVE",
      createdById: admin.id,
    },
  });
  await audit(admin.id, "company_mailbox.create", address);

  return { ok: true, address, password };
}

/**
 * Create any of the default starter mailboxes (admin@, support@, santino@) that
 * don't already exist. Returns the created addresses + their one-time passwords.
 */
export async function createDefaultCompanyMailboxes(): Promise<
  Ok<{ created: Array<{ address: string; password: string }>; skipped: string[] }> | Err
> {
  await requireArea("platform");
  if (!mailcowConfigured()) {
    return { ok: false, error: "Mail hosting is not configured (MAILCOW_API_URL / MAILCOW_API_KEY)." };
  }
  const created: Array<{ address: string; password: string }> = [];
  const skipped: string[] = [];
  for (const lp of DEFAULT_COMPANY_LOCALPARTS) {
    const res = await createCompanyMailbox(lp);
    if (res.ok) created.push({ address: res.address, password: res.password });
    else skipped.push(`${lp}@${COMPANY_MAIL_DOMAIN}`);
  }
  return { ok: true, created, skipped };
}

/** Reveal an existing mailbox's stored password (decrypted). */
export async function revealCompanyMailboxPassword(
  id: string
): Promise<Ok<{ address: string; password: string }> | Err> {
  const admin = await requireArea("platform");
  const box = await db.companyMailbox.findUnique({ where: { id } });
  if (!box) return { ok: false, error: "Mailbox not found." };
  const password = decryptSecret(box.passwordEnc);
  if (!password) return { ok: false, error: "No stored password for this mailbox." };
  await audit(admin.id, "company_mailbox.reveal", box.address);
  return { ok: true, address: box.address, password };
}

/** Reset a mailbox password to a new strong value; returns it once. */
export async function resetCompanyMailboxPassword(
  id: string
): Promise<Ok<{ address: string; password: string }> | Err> {
  const admin = await requireArea("platform");
  if (!mailcowConfigured()) return { ok: false, error: "Mail hosting is not configured." };
  const box = await db.companyMailbox.findUnique({ where: { id } });
  if (!box) return { ok: false, error: "Mailbox not found." };
  const password = generatePassword();
  try {
    await mcSetMailboxPassword(box.address, password);
  } catch (err) {
    return { ok: false, error: safeMailError(err) };
  }
  await db.companyMailbox.update({ where: { id }, data: { passwordEnc: encryptSecret(password), status: "ACTIVE" } });
  await audit(admin.id, "company_mailbox.reset_password", box.address);
  return { ok: true, address: box.address, password };
}

/** Delete a company mailbox from Mailcow and the database. */
export async function deleteCompanyMailbox(id: string): Promise<{ ok: true } | Err> {
  const admin = await requireArea("platform");
  const box = await db.companyMailbox.findUnique({ where: { id } });
  if (!box) return { ok: false, error: "Mailbox not found." };
  if (mailcowConfigured()) {
    try {
      await mcDeleteMailbox(box.address);
    } catch (err) {
      // If Mailcow refused (not merely unreachable), surface it; don't orphan the row.
      if (!isMailcowUnreachable(err)) return { ok: false, error: safeMailError(err) };
    }
  }
  await db.companyMailbox.delete({ where: { id } });
  await audit(admin.id, "company_mailbox.delete", box.address);
  return { ok: true };
}

