136	/**
137	 * Adopt mailboxes that exist on Mailcow but have no local `Mailbox` row.
138	 *
139	 * WHY: `resolveMailbox` read ONLY `db.mailbox`, so a mailbox created directly on
140	 * the mail server — or one whose row was lost — was invisible in the portal even
141	 * though real mail was landing in it ("its not detecting the mailbox that i
142	 * already have on this account"). This reconciles the two.
143	 *
144	 * OWNERSHIP GUARD — the whole point of this function is that it MUST NOT become
145	 * a way to acquire someone else's mailbox:
146	 *   1. Only domains on a non-cancelled subscription owned by THIS user are read.
147	 *   2. Only subscriptions with `verified === true` are eligible. Owning a
148	 *      subscription ROW is not proof of owning the DOMAIN — an unverified
149	 *      external subscription is just a claim, and adopting on a claim would
150	 *      re-open the cross-tenant takeover fixed on 2026-07-25 by a side door.
151	 *   3. `Mailbox.address` is globally `@unique`, and we skip any address that
152	 *      already has a row, so a mailbox another tenant legitimately holds is
153	 *      never re-pointed at this user.
154	 *   4. `passwordEnc` is left NULL. We never learn the existing password, so the
155	 *      customer is told to reset it — adoption grants visibility, not access.
156	 *
157	 * Never throws: a Mailcow outage must not turn the mail page into an error.
158	 * Returns the number of rows created.
159	 */
160	export async function discoverMailboxes(userId: string): Promise<number> {
161	  if (!mailcowConfigured()) return 0;
162	
163	  // Guard against hammering Mailcow: the mail page calls this on every load for
164	  // an account with no mailbox, which is exactly the account that reaches here.
165	  const gate = checkRateLimit(`mail:discover:${userId}`, { max: 1, windowMs: 30_000 });
166	  if (!gate.ok) return 0;
167	
168	  const subs = await db.emailSubscription.findMany({
169	    where: { userId, status: { not: "CANCELLED" }, verified: true },
170	    select: { id: true, domainName: true },
171	  });
172	  if (subs.length === 0) return 0;
173	
174	  let created = 0;
175	  for (const sub of subs) {
176	    const domain = sub.domainName.trim().toLowerCase();
177	    if (!domain) continue;
178	
179	    let remote: Awaited<ReturnType<typeof mcListMailboxes>>;
180	    try {
181	      remote = await mcListMailboxes(domain);
182	    } catch (e) {
183	      console.warn(`[mailcow] discovery for ${domain} failed:`, e);
184	      continue;
185	    }
186	    if (remote.length === 0) continue;
187	
188	    const existing = await db.mailbox.findMany({
189	      where: { address: { in: remote.map((m) => m.address) } },
190	      select: { address: true },
191	    });
192	    const known = new Set(existing.map((m) => m.address.toLowerCase()));
193	
194	    for (const m of remote) {
195	      if (known.has(m.address)) continue;
196	      try {
197	        await db.mailbox.create({
198	          data: {
199	            subscriptionId: sub.id,
200	            address: m.address,
201	            quotaMB: m.quotaBytes > 0 ? Math.round(m.quotaBytes / (1024 * 1024)) : null,
202	            status: m.active ? "ACTIVE" : "SUSPENDED",
203	            displayName: m.name && m.name !== m.address ? m.name : null,
204	          },
205	        });
206	        created++;
207	      } catch {
208	        // Unique-violation race (two tabs discovering at once) — the row exists
209	        // now either way, which is the outcome we wanted.
210	      }
211	    }
212	  }
213	
214	  if (created > 0) {
215	    await db.auditLog
216	      .create({ data: { userId, action: "mailbox.discover", detail: `adopted ${created} from mail server` } })
217	      .catch(() => {});
218	  }
219	  return created;
220	}
