436	/** Map an IMAP special-use flag / folder name to our MailFolderRole. */
437	export function folderRole(path: string, specialUse?: string): MailFolderRole {
438	  const su = (specialUse || "").toLowerCase();
439	  if (su === "\\inbox" || path.toUpperCase() === "INBOX") return "inbox";
440	  switch (su) {
441	    case "\\sent":
442	      return "sent";
443	    case "\\drafts":
444	      return "drafts";
445	    case "\\trash":
446	      return "trash";
447	    case "\\junk":
448	      return "junk";
449	    case "\\archive":
450	    case "\\all":
451	      return "archive";
452	  }
453	  // Fall back to common folder names for servers that don't advertise SPECIAL-USE.
454	  const leaf = (path.split(/[/.]/).pop() || path).toLowerCase();
455	  if (leaf === "inbox") return "inbox";
456	  if (["sent", "sent items", "sent mail", "sent messages"].includes(leaf)) return "sent";
457	  if (["drafts", "draft"].includes(leaf)) return "drafts";
458	  if (["trash", "deleted", "deleted items", "deleted messages", "bin"].includes(leaf)) return "trash";
459	  if (["junk", "spam", "junk email", "junk e-mail"].includes(leaf)) return "junk";
460	  if (["archive", "archives", "all mail", "all"].includes(leaf)) return "archive";
461	  return "custom";
462	}
