517	/** Read imapflow message flags into the summary booleans. */
518	export function readFlags(flags: Set<string> | undefined): { seen: boolean; flagged: boolean; answered: boolean } {
519	  const f = flags ?? new Set<string>();
520	  return { seen: f.has("\\Seen"), flagged: f.has("\\Flagged"), answered: f.has("\\Answered") };
521	}
