31	/**
32	 * IP allow-list gate for /admin. `allowed_admin_ips` is a comma-separated list of
33	 * literal IPs; empty = no restriction. Fails OPEN (allows) when the list has no
34	 * parseable entries or the requester IP can't be determined, so a bad value can
35	 * never lock every admin out — only an exact match is ever enforced.
36	 * Returns true when access should be REFUSED.
37	 */
38	async function adminIpBlocked(): Promise<boolean> {
39	  const raw = await getSetting("allowed_admin_ips", "");
40	  const entries = raw.split(",").map((s) => s.trim()).filter(Boolean);
41	  if (entries.length === 0) return false; // no restriction configured
42	  const valid = entries.filter(isPlainIp);
43	  if (valid.length === 0) {
44	    console.warn("[admin-ip] allowed_admin_ips is set but has no valid IPs; failing open:", raw);
45	    return false; // malformed -> fail open
46	  }
47	  const hdrs = await headers();
48	  // Trust nginx's X-Real-IP ($remote_addr), which the client cannot forge. Fall
49	  // back to the LAST X-Forwarded-For hop (the one our proxy appended), never the
50	  // client-supplied leftmost entry.
51	  const xff = (hdrs.get("x-forwarded-for") ?? "").split(",").map((s) => s.trim()).filter(Boolean);
52	  const ip = hdrs.get("x-real-ip")?.trim() || xff[xff.length - 1] || "";
53	  if (!ip) {
54	    console.warn("[admin-ip] could not determine requester IP; failing open");
55	    return false;
56	  }
57	  return !valid.includes(ip);
58	}
