"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { entryForPath, hrefMatches, type SubTabItem } from "@/lib/admin-groups";

/**
 * Horizontal pill/tab bar for one admin entry's members. Highlights the active
 * item via usePathname (detail routes light up their tab too). Renders nothing
 * for a single-member entry — there is nothing to switch between.
 */
export function SubTabs({
  items,
  badges,
}: {
  items: SubTabItem[];
  /** Per-route attention counts, keyed by href. Shown as a pill on the tab. */
  badges?: Record<string, number>;
}) {
  const pathname = usePathname();
  if (items.length < 2) return null;

  return (
    <nav className="mb-6 flex flex-wrap items-center gap-1.5 border-b border-white/[0.06] pb-3">
      {items.map((item) => {
        const active = hrefMatches(item.href, pathname);
        const count = badges?.[item.href] ?? 0;
        return (
          <Link
            key={item.href}
            href={item.href}
            className={`flex items-center gap-2 rounded-full px-3.5 py-1.5 text-[13px] font-medium transition-colors ${
              active
                ? "bg-brand-500/15 text-brand-200 ring-1 ring-inset ring-brand-500/40"
                : "text-slate-400 hover:bg-white/[0.05] hover:text-slate-200"
            }`}
          >
            {item.label}
            {count > 0 && (
              <span
                className={`flex h-[18px] min-w-[18px] items-center justify-center rounded-full px-1.5 text-[10px] font-semibold text-white ${
                  active ? "bg-brand-500" : "bg-brand-500/80"
                }`}
              >
                {count > 99 ? "99+" : count}
              </span>
            )}
          </Link>
        );
      })}
    </nav>
  );
}

/**
 * Auto-resolving sub-tab bar. Reads the current path, finds the top-level admin
 * entry that owns it and renders that entry's <SubTabs />. Dropped once into the
 * admin layout so every consolidated page gets its sub-navigation without
 * per-page wiring. Renders nothing for paths outside the IA.
 */
export function AdminSubTabs({
  badges,
  allowed,
}: {
  /** Per-route attention counts, keyed by href (same map the sidebar uses). */
  badges?: Record<string, number>;
  /**
   * Hrefs this role may reach, as computed by the layout with canAccessHref().
   * Omitted = no filtering. Keeps a SUPPORT/BILLING user from seeing tabs that
   * would only bounce them back to /admin.
   */
  allowed?: string[];
}) {
  const pathname = usePathname();
  const entry = entryForPath(pathname);
  if (!entry) return null;
  const items = allowed ? entry.tabs.filter((t) => allowed.includes(t.href)) : entry.tabs;
  return <SubTabs items={items} badges={badges} />;
}

