input.new_string:
// Which mailbox to open first. Honour `?mailbox=` when it names a real company
// mailbox; otherwise start on the first one (listCompanyMailboxes orders by
// address asc, so this is stable). We then try that mailbox and — if it can't
// be reached — fall back to the remaining ones IN ORDER.
//
// WHY the fallback: a company mailbox that can't be opened (its Mailcow
// password was rotated out-of-band, the box is mid-provision, a transient IMAP
// hiccup) used to dead-end the WHOLE admin inbox on the error card below — even
// though the admin has three other perfectly readable company mailboxes. One
// bad default made every company mailbox unreadable in the portal. Landing on
// the first mailbox that actually loads keeps the inbox usable; the switcher
// still lists them all, so the admin can jump to any specific one.
const wanted = requested?.trim().toLowerCase();
const preferred =
  wanted && mailboxes.some((m) => m.address.toLowerCase() === wanted) ? wanted : mailboxes[0].address;
const candidates = [preferred, ...mailboxes.map((m) => m.address).filter((a) => a !== preferred)];

let active = preferred;
let folders: MailFolder[] = [];
let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
let inboxPath = "INBOX";

for (const address of candidates) {
  try {
    const f = await listFolders(address);
    if (f.length === 0) continue;
    const path = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
    const msgs = await listMessages(path, 1, undefined, address);
    active = address;
    folders = f;
    inboxPath = path;
    list = msgs;
    break;
  } catch {
    // Try the next company mailbox; only report failure if none load.
  }
}

if (folders.length === 0) {
  return (
    <div className="space-y-6">
      <PageHeader title="Company inbox" sub={preferred} />
      <div className="card p-6 text-center text-sm text-slate-400">
        Couldn&apos;t reach the mail server for any company mailbox.
        If a mailbox was just created, give it a moment and reload; otherwise reset its password on the{" "}
        <Link href="/admin/mailboxes" className="text-brand-300 hover:underline">
          Mailboxes
        </Link>{" "}
        page.
      </div>
    </div>
  );
}
